#!/usr/bin/env python3
"""MyAgent 云端全栈更新 — 粘贴到云端终端: python3 update.py"""
import os, sys, json, shutil, subprocess, pathlib, time

# ---- 0. 定位项目目录 ----
for candidate in [
    "/workspace/template-repos/template-2603/repo",
    *(p.parent.parent for p in pathlib.Path("/").rglob("*/backend/main.py") if p.is_file())
]:
    if (pathlib.Path(candidate) / "backend" / "main.py").exists():
        ROOT = pathlib.Path(candidate)
        break
else:
    print("❌ 找不到 MyAgent 项目目录")
    sys.exit(1)

print(f"📂 {ROOT}")
os.chdir(ROOT)

# ---- 1. 写入 system_routes.py ----
print("[1/7] /api/system 端点")
(ROOT / "backend/api/routes").mkdir(parents=True, exist_ok=True)
(ROOT / "backend/api/routes/system_routes.py").write_text(base64.b64decode("").decode("utf-8"), encoding="utf-8")
print("  ✓ system_routes.py")

# ---- 2. 注册路由 + 修复 master + dispatcher + start.sh ----
print("[2/7] 注册路由 + 修复")
mp = ROOT / "backend/main.py"
s = mp.read_text()
if "system_routes" not in s:
    s = s.replace("project_routes", "project_routes, system_routes", 1)
    s = s.replace(
        "app.include_router(project_routes.router)",
        "app.include_router(project_routes.router)\napp.include_router(system_routes.router)", 1
    )
    mp.write_text(s)
    print("  ✓ main.py")

mp = ROOT / "backend/core/role/master.py"
s = mp.read_text()
old = "抱歉，没有匹配到合适的角色来处理你的请求。"
new = "匹配到的角色未能成功执行任务。可能原因：LLM 超时或任务对模型过于复杂。建议简化请求重试。"
if old in s and new not in s:
    mp.write_text(s.replace(old, new, 1))
    print("  ✓ master.py 错误信息")

dp = ROOT / "data/dispatcher_config.json"
d = json.loads(dp.read_text(encoding='utf-8-sig'))
g2 = d["parallelization"]["parallel_matrix"]["gpu2_roles"]
if "experience_evaluator" not in g2:
    g2.append("experience_evaluator")
    dp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding='utf-8-sig')
    print("  ✓ dispatcher_config")

sp = ROOT / "start.sh"
s = sp.read_text()
if "LLAMA_PORT" not in s or '--port "$LLAMA_PORT"' not in s:
    s = s.replace("CTX_SIZE=\"${CTX_SIZE:-8192}\"",
        "CTX_SIZE=\"${CTX_SIZE:-8192}\"\nNGL=\"${NGL:-99}\"\nLLAMA_PORT=\"${LLAMA_PORT:-8000}\"", 1)
    s = s.replace("--port 8000", '--port "$LLAMA_PORT"')
    s = s.replace("-ngl 99", '-ngl "$NGL"')
    sp.write_text(s)
    print("  ✓ start.sh 参数漂移")

# ---- 3. 写入 ChatView.vue ----
print("[3/7] ChatView.vue")
chat_vue = (ROOT / "frontend/src/views/ChatView.vue")
chat_vue.write_text(base64.b64decode("").decode("utf-8"), encoding="utf-8")
print("  ✓ ChatView.vue")
(ROOT / "frontend/src/views/BrowserView.vue").write_text(base64.b64decode("").decode("utf-8"), encoding="utf-8")
print("  ✓ BrowserView.vue")

# ---- 4. 重建前端 ----
print("[4/7] 重建前端...")
os.chdir(ROOT / "frontend")
if not (ROOT / "frontend/node_modules").exists():
    subprocess.run(["npm", "install"], check=False, capture_output=True)
result = subprocess.run(["npm", "run", "build"], check=False, capture_output=True, text=True)
if result.returncode == 0:
    print("  ✓ 构建成功")
else:
    print(f"  ⚠ 构建警告 (继续...): {result.stderr[-200:]}")
os.chdir(ROOT)

# ---- 5. 复制 dist ----
print("[5/7] 部署 dist...")
dist = ROOT / "frontend/dist"
for target in ["/usr/share/nginx/html", "/var/www/html", "/etc/nginx/html"]:
    tp = pathlib.Path(target)
    try:
        if not tp.exists():
            tp.mkdir(parents=True, exist_ok=True)
        for f in dist.glob("*"):
            dest = tp / f.name
            if f.is_dir():
                shutil.copytree(f, dest, dirs_exist_ok=True)
            else:
                shutil.copy2(f, dest)
        print(f"  ✓ dist → {target}")
        break
    except Exception as e:
        continue
else:
    print("  ⚠ 无法找到 nginx html 目录，dist 在 frontend/dist/")

# ---- 6. 重启 ----
print("[6/7] 重启服务...")
subprocess.run(["bash", "stop.sh"], check=False, capture_output=True)
time.sleep(3)
subprocess.run(["bash", "start.sh"], check=True)
time.sleep(10)

# ---- 7. 验证 ----
print("[7/7] 验证...")
try:
    import urllib.request
    for label, url in [("/api/system", "http://localhost:8080/api/system"),
                        ("/api/health", "http://localhost:8080/api/health"),
                        ("前端", "http://localhost:8088/")]:
        try:
            req = urllib.request.urlopen(url, timeout=5)
            print(f"  {label} → HTTP {req.getcode()}")
        except Exception as e:
            print(f"  {label} → ❌ {e}")
except:
    pass

print("\n🎉 完成！刷新浏览器看新的 Agent 平台界面。")
